    };

    let category = match ui.prompt(&category_prompt)? {
        PromptResult::String(s) => s,
        _ => "other".to_string(),
    };

    let prompt = Prompt {
        key: "feedback_message".to_string(),
        question: "Describe your feedback:".to_string(),
        prompt_type: PromptType::Input,
        default: None,
    };

