//! Session wrapper for CLI commands.
//!
//! This module provides session tracking integration for CLI command execution.

use anyhow::Result;

use crate::session::{default_store_path, Session, SessionId, SessionMetadata, SessionStore};

/// Wraps command execution with session tracking.
pub struct SessionWrapper {
    store: SessionStore,
    current_id: SessionId,
    metadata: SessionMetadata,
    stdout_buffer: Vec<u8>,
    stderr_buffer: Vec<u8>,
}

impl SessionWrapper {
    /// Create a new session wrapper.
    pub fn new(command: &str, args: Vec<String>) -> Self {
        Self {
            store: SessionStore::new(default_store_path()),
            current_id: SessionId::new(),
            metadata: SessionMetadata::new(command, args),
            stdout_buffer: Vec::new(),
            stderr_buffer: Vec::new(),
        }
    }

    /// Get the current session ID.
    pub fn session_id(&self) -> &SessionId {
        &self.current_id
    }

    /// Get mutable access to metadata for adding context.
    pub fn metadata_mut(&mut self) -> &mut SessionMetadata {
        &mut self.metadata
    }

    /// Capture stdout.
    pub fn capture_stdout(&mut self, s: &str) {
        self.stdout_buffer.extend_from_slice(s.as_bytes());
    }

    /// Capture stderr.
    pub fn capture_stderr(&mut self, s: &str) {
        self.stderr_buffer.extend_from_slice(s.as_bytes());
    }

    /// Finalize and save the session.
    pub fn finalize(mut self, exit_code: i32) -> Result<SessionId> {
        let stdout = String::from_utf8_lossy(&self.stdout_buffer).to_string();
        let stderr = String::from_utf8_lossy(&self.stderr_buffer).to_string();

        self.metadata.finalize(exit_code, stdout, stderr);

        let session = Session {
            id: self.current_id.clone(),
            metadata: self.metadata,
        };

        self.store.save(&session)?;

        // Cleanup old sessions (keep last 100)
        let _ = self.store.cleanup(100);

        Ok(self.current_id)
    }

    /// Get the latest session ID (for feedback command).
    pub fn get_latest_session_id() -> Result<Option<SessionId>> {
        let store = Self::get_store();
        Ok(store.get_latest()?.map(|s| s.id))
    }

    /// Get the session store for reading sessions.
    pub fn get_store() -> SessionStore {
        SessionStore::new(default_store_path())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    // Use a custom store for testing to avoid polluting the real store
    fn create_test_wrapper(
        command: &str,
        args: Vec<String>,
        store_path: std::path::PathBuf,
    ) -> SessionWrapper {
        SessionWrapper {
            store: SessionStore::new(store_path),
            current_id: SessionId::new(),
            metadata: SessionMetadata::new(command, args),
            stdout_buffer: Vec::new(),
            stderr_buffer: Vec::new(),
        }
    }

    #[test]
    fn session_wrapper_creation() {
        let wrapper = SessionWrapper::new("run", vec!["--verbose".to_string()]);
        assert!(wrapper.session_id().as_str().starts_with("sess_"));
    }

    #[test]
    fn session_wrapper_capture_output() {
        let temp = TempDir::new().unwrap();
        let mut wrapper = create_test_wrapper("list", vec![], temp.path().join("sessions"));

        wrapper.capture_stdout("Hello\n");
        wrapper.capture_stdout("World\n");
        wrapper.capture_stderr("Warning: something\n");

        let id = wrapper.finalize(0).unwrap();

        // Verify the session was saved
        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert!(session.metadata.stdout.contains("Hello"));
        assert!(session.metadata.stdout.contains("World"));
        assert!(session.metadata.stderr.contains("Warning"));
    }

    #[test]
    fn session_wrapper_metadata_modification() {
        let temp = TempDir::new().unwrap();
        let mut wrapper = create_test_wrapper("run", vec![], temp.path().join("sessions"));

        wrapper.metadata_mut().set_flag("verbose", true);
        wrapper.metadata_mut().context.workflow = Some("default".to_string());

        let id = wrapper.finalize(0).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert_eq!(
            session.metadata.flags.get("verbose"),
            Some(&serde_json::json!(true))
        );
        assert_eq!(
            session.metadata.context.workflow,
            Some("default".to_string())
        );
    }

    #[test]
    fn session_wrapper_finalize_exit_code() {
        let temp = TempDir::new().unwrap();
        let wrapper = create_test_wrapper("run", vec![], temp.path().join("sessions"));

        let id = wrapper.finalize(1).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert_eq!(session.metadata.exit_code, Some(1));
    }

    #[test]
    fn session_wrapper_cleanup_old_sessions() {
        let temp = TempDir::new().unwrap();
        let store_path = temp.path().join("sessions");

        // Create 105 sessions
        for i in 0..105 {
            let wrapper = create_test_wrapper(&format!("cmd{}", i), vec![], store_path.clone());
            wrapper.finalize(0).unwrap();
            std::thread::sleep(std::time::Duration::from_millis(2));
        }

        let store = SessionStore::new(&store_path);
        let sessions = store.list_recent(usize::MAX).unwrap();

        // Should have at most 100 sessions due to cleanup
        assert!(sessions.len() <= 100);
    }

    #[test]
    fn session_wrapper_get_store() {
        // Test that get_store returns a valid store
        let store = SessionWrapper::get_store();
        // Just check the path is set correctly
        assert!(store.path().ends_with("sessions"));
    }

    #[test]
    fn session_wrapper_get_latest_session_id_empty_store() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let latest = store.get_latest().unwrap();
        assert!(latest.is_none());
    }

    #[test]
    fn session_wrapper_get_latest_session_id_returns_most_recent() {
        let temp = TempDir::new().unwrap();
        let store_path = temp.path().join("sessions");

        // Create two sessions with a small delay so timestamps differ
        let first = create_test_wrapper("first", vec![], store_path.clone());
        let _first_id = first.finalize(0).unwrap();
        std::thread::sleep(std::time::Duration::from_millis(2));

        let second = create_test_wrapper("second", vec![], store_path.clone());
        let second_id = second.finalize(0).unwrap();

        let store = SessionStore::new(&store_path);
        let latest = store.get_latest().unwrap().expect("should have a session");
        assert_eq!(latest.id, second_id);
        assert_eq!(latest.metadata.command, "second");
    }

    #[test]
    fn session_wrapper_capture_multiple_calls() {
        let temp = TempDir::new().unwrap();
        let mut wrapper = create_test_wrapper("test", vec![], temp.path().join("sessions"));

        // Multiple capture calls
        wrapper.capture_stdout("line1\n");
        wrapper.capture_stdout("line2\n");
        wrapper.capture_stdout("line3\n");
        wrapper.capture_stderr("err1\n");
        wrapper.capture_stderr("err2\n");

        let id = wrapper.finalize(0).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert!(session.metadata.stdout.contains("line1"));
        assert!(session.metadata.stdout.contains("line2"));
        assert!(session.metadata.stdout.contains("line3"));
        assert!(session.metadata.stderr.contains("err1"));
        assert!(session.metadata.stderr.contains("err2"));
    }

    #[test]
    fn session_wrapper_session_id_accessor() {
        let temp = TempDir::new().unwrap();
        let wrapper = create_test_wrapper("cmd", vec![], temp.path().join("sessions"));

        let id = wrapper.session_id();
        assert!(id.as_str().starts_with("sess_"));
    }

    #[test]
    fn session_wrapper_with_args() {
        let temp = TempDir::new().unwrap();
        let wrapper = create_test_wrapper(
            "run",
            vec!["--verbose".to_string(), "--force".to_string()],
            temp.path().join("sessions"),
        );

        let id = wrapper.finalize(0).unwrap();

        let store = SessionStore::new(temp.path().join("sessions"));
        let session = store.load(&id).unwrap();

        assert_eq!(session.metadata.command, "run");
        assert_eq!(session.metadata.args, vec!["--verbose", "--force"]);
    }
}

//! Low-level terminal surface for the run path.
//!
//! `TerminalSurface` owns the [`MultiProgress`] that coordinates pinned and
//! transient regions during a workflow run. It is the only place that
//! touches the multi-progress directly — higher layers (`WorkflowDisplay`,
//! `StepDisplay`) only see *regions*, not bars.
//!
//! ## Regions, top to bottom
//!
//! 1. **Scrollback** — printed via [`TerminalSurface::println`]. Step
//!    headers, status messages, error blocks, summaries — anything
//!    non-spinner.
//! 2. **Transient region** — currently-running step's spinner with its
//!    bounded live-output tail. Mounted via
//!    [`TerminalSurface::transient_above_pinned`].
//! 3. **Pinned region** — workflow progress bar, pinned at the bottom.
//!    Mounted via [`TerminalSurface::pin_bottom`].
//!
//! ## Region clearing
//!
//! [`TransientRegion`] takes a `max_lines` hint at construction time so
//! callers can reason about the maximum vertical extent of the spinner
//! and its live-output tail. Clearing on drop currently delegates to
//! `indicatif::ProgressBar::finish_and_clear`, which tracks the bar's
//! last rendered height and clears that many rows. An earlier version
//! of this module padded every message to exactly `max_lines` blank
//! rows before clearing, but that pattern caused trailing blank rows
//! to leak into scrollback on drop — `finish_and_clear` already handles
//! the multi-line case correctly in current `indicatif` versions.
//!
//! ## Cursor freeing
//!
//! Interactive prompts (dialoguer) need exclusive access to the cursor.
//! [`TerminalSurface::with_cursor_freed`] hides the multi-progress draw
//! target for the duration of a closure and restores it afterwards.

use indicatif::{MultiProgress, ProgressBar, ProgressDrawTarget, ProgressStyle};
use std::sync::Arc;

/// Owns the [`MultiProgress`] that coordinates draw regions during a run.
///
/// Construct via [`TerminalSurface::new`] and share via the returned
/// [`Arc`]. Both the workflow display and per-step displays hold a clone of
/// the `Arc`, but only the surface itself owns mutable access to the
/// underlying multi-progress.
pub struct TerminalSurface {
    multi: MultiProgress,
}

impl TerminalSurface {
    /// Create a new surface, returning a shared handle.
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            multi: MultiProgress::new(),
        })
    }

    /// Try to create a surface for the current terminal.
    ///
    /// Returns `None` when the terminal can't render progress bars —
    /// non-TTY stderr, `NO_COLOR`, or `TERM=dumb`. In those cases
    /// `MultiProgress::stderr()` is silently hidden by indicatif and
    /// every `println` call becomes a no-op, swallowing all output.
    /// Callers should fall back to plain stdout writes (typically by
    /// using [`crate::runner::display::NonInteractiveWorkflowDisplay`]).
    pub fn try_new() -> Option<Arc<Self>> {
        if !console::Term::stderr().features().colors_supported() {
            return None;
        }
        Some(Self::new())
    }

    /// Create a hidden surface for tests — no output is drawn.
    pub fn hidden() -> Arc<Self> {
        Arc::new(Self {
            multi: MultiProgress::with_draw_target(ProgressDrawTarget::hidden()),
        })
    }

    /// Print a line into scrollback, above any pinned/transient bars.
    pub fn println(&self, line: &str) {
        // `MultiProgress::println` writes above all managed bars. If draw
        // is hidden (tests / silent mode), the call is a no-op rather than
        // an error — discard the result either way.
        let _ = self.multi.println(line);
    }

    /// Pin a bar at the bottom of the live region.
    ///
    /// Used once per run, by the workflow display. The returned [`PinnedBar`]
    /// keeps the bar live until dropped; on drop, the bar is cleared.
    pub fn pin_bottom(self: &Arc<Self>, bar: ProgressBar) -> PinnedBar {
        let bar = self.multi.add(bar);
        PinnedBar { bar: Some(bar) }
    }

