1	//! Interactive user interface components.
2	//!
3	//! This module provides:
4	//! - [`UserInterface`] trait for UI abstraction
5	//! - [`TerminalUI`] for interactive terminal usage
6	//! - [`NonInteractiveUI`] for CI/headless environments
7	//! - Prompts, spinners, progress indicators, and tables
8	//!
9	//! # Example
10	//!
11	//! ```
12	//! use bivvy::ui::{create_ui, OutputMode};
13	//!
14	//! // Use non-interactive mode for testability
15	//! let mut ui = create_ui(false, OutputMode::Quiet);
16	//! ui.show_header("My App");
17	//! ui.success("Setup complete!");
18	//! ```
19	
20	pub mod hints;
21	pub mod icons;
22	pub mod mock;
23	pub mod non_interactive;
24	pub mod output;
25	pub mod preflight;
26	pub mod presenter;
27	pub mod progress;
28	pub mod prompts;
29	pub mod spinner;
30	pub mod surface;
31	pub mod table;
32	pub mod terminal;
33	pub mod theme;
34	
35	pub use icons::StatusKind;
36	pub use mock::{MockSpinner, MockUI};
37	pub use non_interactive::NonInteractiveUI;
38	pub use output::{
39	    check_passed_label, rerun_prompt_label, satisfaction_label, FixOutputSink, Output, OutputMode,
40	    VerboseStreamSink,
41	};
42	pub use preflight::PreflightCollector;
43	pub use presenter::EventPresenter;
44	pub use progress::{format_duration, format_relative_time, StepProgress};
45	pub use prompts::prompt_user;
46	pub use spinner::{step_spinner, ProgressSpinner};
47	pub use surface::TerminalSurface;
